// Robust solution: Composition + Forwarding (Decorator / Wrapper Pattern)
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class ForwardingSet<E> implements Set<E> {
    private final Set<E> s;
    public ForwardingSet(Set<E> s) { this.s = s; }

    public int size() { return s.size(); }
    public boolean isEmpty() { return s.isEmpty(); }
    public boolean contains(Object o) { return s.contains(o); }
    public boolean add(E e) { return s.add(e); }
    public boolean addAll(Collection<? extends E> c) { return s.addAll(c); }
    // ...forward remaining Set methods
}

public class InstrumentedSet<E> extends ForwardingSet<E> {
    private int addCount = 0;
    public InstrumentedSet(Set<E> s) { super(s); }

    @Override public boolean add(E e) { addCount++; return super.add(e); }
    @Override public boolean addAll(Collection<? extends E> c) {
        addCount += c.size();
        return super.addAll(c); // Independent of Set implementation details!
    }
    public int getAddCount() { return addCount; }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Wraps ANY Set implementation (HashSet, TreeSet, LinkedHashSet)!
        InstrumentedSet<String> s = new InstrumentedSet<>(new HashSet<>());
        s.addAll(List.of("Snap", "Crackle", "Pop"));
        System.out.println("Add count: " + s.getAddCount()); // Correctly prints 3!
    }
}
